## File 2: data.js

```javascript
/**
 * @fileoverview Data storage module for the Book REST API.
 * 
 * This module manages all book data using an in-memory array.
 * We choose in-memory storage for this educational example because:
 * 1. It keeps the code focused on API concepts without database complexity
 * 2. It demonstrates core CRUD operations clearly
 * 3. It's fast and requires no setup
 * 
 * Trade-offs of this approach:
 * - Data is lost when the server restarts (no persistence)
 * - Not suitable for production use
 * - No concurrent access handling needed in single-threaded Node.js
 */

// In-memory array to store all books.
// We use an array because:
// - Books are naturally ordered by creation time
// - Arrays provide O(1) access by index (though we'll use findIndex for ID lookup)
// - Simple iteration for filtering and statistics
const books = [];

/**
 * Generates a unique numeric ID for new books.
 * 
 * We use a simple incrementing counter instead of UUIDs because:
 * 1. Numeric IDs are simpler to understand in an educational context
 * 2. They're more readable in URLs (/books/1 vs /books/a3f2b)
 * 3. For production, we'd use crypto.randomUUID() or a database sequence
 * 
 * @returns {number} The next available book ID
 */
function generateId() {
    // If no books exist yet, start at 1
    if (books.length === 0) {
        return 1;
    }

    // Find the maximum existing ID and add 1
    // This ensures uniqueness even if books are deleted
    const maxId = Math.max(...books.map(book => book.id));
    return maxId + 1;
}

/**
 * Retrieves all books from storage.
 * 
 * @returns {Array<Object>} Array of all book objects
 */
function getAllBooks() {
    // Return a copy to prevent external mutation of our internal array
    return [...books];
}

/**
 * Finds a single book by its ID.
 * 
 * We use findIndex instead of find because:
 * - It's slightly more performant for large arrays (stops at first match)
 * - It returns -1 if not found, which is easier to check explicitly
 * 
 * @param {number} id - The numeric ID of the book to find
 * @returns {Object|null} The book object if found, null otherwise
 */
function getBookById(id) {
    const index = books.findIndex(book => book.id === id);

    // Return the book or null if not found
    return index !== -1 ? books[index] : null;
}

/**
 * Adds a new book to storage.
 * 
 * @param {Object} bookData - The book data to add (without ID)
 * @returns {Object} The newly created book with assigned ID
 */
function createBook(bookData) {
    // Generate a unique ID for the new book
    const id = generateId();

    // Create the complete book object with timestamp
    const newBook = {
        id,
        title: bookData.title,
        author: bookData.author,
        genre: bookData.genre,
        publishedYear: bookData.publishedYear,
        rating: bookData.rating,
        createdAt: new Date().toISOString() // ISO 8601 format for consistency
    };

    // Add to the end of the array (newest books last)
    books.push(newBook);

    return newBook;
}

/**
 * Updates an existing book by ID.
 * 
 * @param {number} id - The ID of the book to update
 * @param {Object} updates - Fields to update (partial update allowed)
 * @returns {Object|null} The updated book or null if not found
 */
function updateBook(id, updates) {
    const index = books.findIndex(book => book.id === id);

    // Return null if book doesn't exist
    if (index === -1) {
        return null;
    }

    // Create updated book by merging existing data with new values
    // We use spread operator to create a new object (immutability best practice)
    const updatedBook = {
        ...books[index], // Copy all existing fields
        ...updates,      // Override with new values
        updatedAt: new Date().toISOString() // Track when update occurred
    };

    // Replace the old book in the array
    books[index] = updatedBook;

    return updatedBook;
}

/**
 * Deletes a book by ID.
 * 
 * @param {number} id - The ID of the book to delete
 * @returns {boolean} True if deleted, false if not found
 */
function deleteBook(id) {
    const index = books.findIndex(book => book.id === id);

    // Return false if book doesn't exist
    if (index === -1) {
        return false;
    }

    // Remove the book from the array using splice
    // splice modifies the original array in-place
    books.splice(index, 1);

    return true;
}

/**
 * Calculates statistics about all books.
 * 
 * @returns {Object} Statistics including total count, average rating, and distributions
 */
function getStats() {
    if (books.length === 0) {
        // Return default stats when no books exist
        return {
            totalBooks: 0,
            averageRating: 0,
            genreDistribution: {},
            authorCount: 0,
            yearRange: null
        };
    }

    // Calculate total and average rating using reduce for efficiency
    const totalRating = books.reduce((sum, book) => sum + book.rating, 0);
    const averageRating = parseFloat((totalRating / books.length).toFixed(2));

    // Count books by genre using reduce to build distribution object
    const genreDistribution = books.reduce((acc, book) => {
        acc[book.genre] = (acc[book.genre] || 0) + 1;
        return acc;
    }, {});

    // Get unique authors count
    const uniqueAuthors = new Set(books.map(book => book.author));

    // Find earliest and latest publication years
    const years = books.map(book => book.publishedYear);
    const yearRange = {
        earliest: Math.min(...years),
        latest: Math.max(...years)
    };

    return {
        totalBooks: books.length,
        averageRating,
        genreDistribution,
        authorCount: uniqueAuthors.size,
        yearRange
    };
}

// Export all functions using CommonJS module syntax
// This allows other files to import and use these functions
module.exports = {
    getAllBooks,
    getBookById,
    createBook,
    updateBook,
    deleteBook,
    getStats
};
```

