/**
 * @fileoverview Custom error classes for the Book REST API.
 * 
 * We create custom error classes instead of using generic Error objects because:
 * 1. They provide specific error types that can be handled differently by middleware
 * 2. They include additional properties (statusCode, isOperational) for better error handling
 * 3. They make debugging easier with descriptive names
 * 4. They follow the principle of "fail fast" with clear error messages
 */

/**
 * Base custom error class that all API errors will extend.
 * 
 * @extends Error
 */
class AppError extends Error {
    /**
     * Creates a new AppError instance.
     * 
     * @param {string} message - Human-readable error message
     * @param {number} statusCode - HTTP status code for the error (default: 500)
     */
    constructor(message, statusCode = 500) {
        super(message); // Call parent Error constructor with message

        // Set the HTTP status code
        this.statusCode = statusCode;

        // Mark as operational error (expected in production)
        // This distinguishes it from programming errors that need fixing
        this.isOperational = true;

        // Capture stack trace for debugging
        Error.captureStackTrace(this, this.constructor);
    }
}

/**
 * Error class for 404 Not Found responses.
 * 
 * Used when a requested resource doesn't exist.
 */
class NotFoundError extends AppError {
    /**
     * Creates a NotFoundError instance.
     * 
     * @param {string} resourceName - Name of the resource not found (e.g., "Book")
     * @param {*} identifier - The ID or identifier that wasn't found
     */
    constructor(resourceName = 'Resource', identifier) {
        // Call parent constructor with descriptive message and 404 status
        super(
            `${resourceName} with id ${identifier} not found`,
            404
        );

        // Set error name for easier identification in logs
        this.name = 'NotFoundError';
    }
}

/**
 * Error class for 400 Bad Request responses.
 * 
 * Used when client sends invalid data or missing required fields.
 */
class ValidationError extends AppError {
    /**
     * Creates a ValidationError instance.
     * 
     * @param {string} message - Description of what validation failed
     * @param {Array<Object>} [details] - Array of specific validation errors
     */
    constructor(message, details = []) {
        // Call parent constructor with 400 status
        super(message, 400);

        this.name = 'ValidationError';

        // Store additional validation details if provided
        this.details = details;
    }
}

/**
 * Error class for 500 Internal Server Error responses.
 * 
 * Used for unexpected server-side errors that aren't operational.
 */
class InternalServerError extends AppError {
    /**
     * Creates an InternalServerError instance.
     * 
     * @param {string} message - Description of the error
     * @param {Error} [originalError] - The original error that caused this (for logging)
     */
    constructor(message = 'Internal server error', originalError) {
        // Call parent constructor with 500 status
        super(message, 500);

        this.name = 'InternalServerError';

        // Store the original error for debugging (don't expose to client)
        if (originalError) {
            this.originalError = originalError;
        }
    }
}

// Export all custom error classes
module.exports = {
    AppError,
    NotFoundError,
    ValidationError,
    InternalServerError
};
```

