```javascript
/**
 * @fileoverview Validation middleware for the Book REST API.
 * 
 * This module contains validation functions that check incoming request data
 * before it reaches the route handlers. We separate validation into its own
 * module because:
 * 1. It keeps route handlers clean and focused on business logic
 * 2. Validation rules can be reused across multiple endpoints
 * 3. It makes testing easier (unit test validators separately)
 * 4. It follows the Single Responsibility Principle
 */

const { ValidationError } = require('../errors');

/**
 * Validates book creation data.
 * 
 * @param {Object} body - The request body containing book data
 * @returns {void} Throws ValidationError if validation fails
 * 
 * Validation rules:
 * - title: required, string, minimum 1 character
 * - author: required, string, minimum 1 character  
 * - genre: required, string, must be one of predefined genres
 * - publishedYear: required, integer between 1000 and current year
 * - rating: optional, number between 0 and 5
 */
function validateCreateBook(body) {
    const errors = [];

    // Check title
    if (!body.title || typeof body.title !== 'string' || body.title.trim().length === 0) {
        errors.push({ field: 'title', message: 'Title is required and must be a non-empty string' });
    }

    // Check author
    if (!body.author || typeof body.author !== 'string' || body.author.trim().length === 0) {
        errors.push({ field: 'author', message: 'Author is required and must be a non-empty string' });
    }

    // Check genre with predefined list for consistency
    const validGenres = ['Fiction', 'Non-Fiction', 'Science Fiction', 'Fantasy', 'Mystery', 
                        'Romance', 'Thriller', 'Horror', 'Biography', 'History', 'Science'];

    if (!body.genre || !validGenres.includes(body.genre)) {
        errors.push({ 
            field: 'genre', 
            message: `Genre is required and must be one of: ${validGenres.join(', ')}` 
        });
    }

    // Check publishedYear
    const currentYear = new Date().getFullYear();
    if (!body.publishedYear || !Number.isInteger(body.publishedYear)) {
        errors.push({ field: 'publishedYear', message: 'Published year is required and must be an integer' });
    } else if (body.publishedYear < 1000 || body.publishedYear > currentYear) {
        errors.push({ 
            field: 'publishedYear', 
            message: `Published year must be between 1000 and ${currentYear}` 
        });
    }

    // Check rating (optional but if provided, must be valid)
    if (body.rating !== undefined && body.rating !== null) {
        if (typeof body.rating !== 'number' || body.rating < 0 || body.rating > 5) {
            errors.push({ 
                field: 'rating', 
                message: 'Rating must be a number between 0 and 5' 
            });
        }
    }

    // Throw error if any validation failed
    if (errors.length > 0) {
        throw new ValidationError('Validation failed', errors);
    }
}

/**
 * Validates book update data.
 * 
 * @param {Object} body - The request body containing update fields
 * @returns {void} Throws ValidationError if validation fails
 * 
 * Note: Updates are partial, so we only validate fields that are provided.
 * This allows clients to update just one field without sending all fields.
 */
function validateUpdateBook(body) {
    const errors = [];

    // Only validate fields that are actually present in the request
    if (body.title !== undefined) {
        if (typeof body.title !== 'string' || body.title.trim().length === 0) {
            errors.push({ field: 'title', message: 'Title must be a non-empty string' });
        }
    }

    if (body.author !== undefined) {
        if (typeof body.author !== 'string' || body.author.trim().length === 0) {
            errors.push({ field: 'author', message: 'Author must be a non-empty string' });
        }
    }

    if (body.genre !== undefined) {
        const validGenres = ['Fiction', 'Non-Fiction', 'Science Fiction', 'Fantasy', 'Mystery', 
                            'Romance', 'Thriller', 'Horror', 'Biography', 'History', 'Science'];
        if (!validGenres.includes(body.genre)) {
            errors.push({ 
                field: 'genre', 
                message: `Genre must be one of: ${validGenres.join(', ')}` 
            });
        }
    }

    if (body.publishedYear !== undefined) {
        const currentYear = new Date().getFullYear();
        if (!Number.isInteger(body.publishedYear)) {
            errors.push({ field: 'publishedYear', message: 'Published year must be an integer' });
        } else if (body.publishedYear < 1000 || body.publishedYear > currentYear) {
            errors.push({ 
                field: 'publishedYear', 
                message: `Published year must be between 1000 and ${currentYear}` 
            });
        }
    }

    if (body.rating !== undefined) {
        if (typeof body.rating !== 'number' || body.rating < 0 || body.rating > 5) {
            errors.push({ field: 'rating', message: 'Rating must be a number between 0 and 5' });
        }
    }

    // Throw error if any validation failed
    if (errors.length > 0) {
        throw new ValidationError('Validation failed', errors);
    }
}

/**
 * Validates book ID parameter.
 * 
 * @param {*} id - The ID to validate
 * @returns {void} Throws ValidationError if ID is invalid
 */
function validateId(id) {
    const numericId = parseInt(id, 10);

    // Check if parsing succeeded and result matches original
    if (isNaN(numericId) || String(numericId) !== id) {
        throw new ValidationError('Invalid book ID. Must be a positive integer.');
    }

    if (numericId <= 0) {
        throw new ValidationError('Book ID must be a positive integer.');
    }
}

// Export validation functions
module.exports = {
    validateCreateBook,
    validateUpdateBook,
    validateId
};
