```javascript
/**
 * @fileoverview Book routes for the REST API.
 * 
 * This module defines all HTTP endpoints related to books.
 * We use Express Router to create a modular route handler that can be
 * mounted on the main app. This separation allows us to:
 * 1. Keep route definitions organized by resource
 * 2. Apply middleware specific to book routes
 * 3. Make the code more maintainable as it grows
 * 
 * REST conventions followed:
 * - GET /books - List all books (with optional filtering)
 * - GET /books/:id - Get single book by ID
 * - POST /books - Create new book
 * - PUT /books/:id - Update existing book (full replacement)
 * - DELETE /books/:id - Delete book
 */

const express = require('express');
const router = express.Router();

// Import data access functions
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require('../data');

// Import validation middleware
const { validateCreateBook, validateUpdateBook, validateId } = require('../middleware/validation');

// Import custom error classes
const { NotFoundError } = require('../errors');

/**
 * GET /books
 * 
 * Retrieves all books with optional filtering.
 * 
 * Query parameters (all optional):
 * - author: Filter by author name (case-insensitive partial match)
 * - genre: Filter by exact genre match
 * - minRating: Filter books with rating >= this value
 * - search: Search in title and author fields
 * 
 * @example
 * GET /books?author=tolkien&genre=Fantasy
 * GET /books?minRating=4.0
 * GET /books?search=harry
 */
router.get('/', (req, res) => {
    try {
        // Get all books from storage
        let result = getAllBooks();

        // Apply filters if query parameters are provided
        const { author, genre, minRating, search } = req.query;

        // Filter by author (case-insensitive partial match)
        if (author) {
            result = result.filter(book => 
                book.author.toLowerCase().includes(author.toLowerCase())
            );
        }

        // Filter by exact genre match
        if (genre) {
            result = result.filter(book => book.genre === genre);
        }

        // Filter by minimum rating
        if (minRating) {
            const minRatingNum = parseFloat(minRating);
            result = result.filter(book => book.rating >= minRatingNum);
        }

        // Search in title and author fields
        if (search) {
            const searchLower = search.toLowerCase();
            result = result.filter(book => 
                book.title.toLowerCase().includes(searchLower) ||
                book.author.toLowerCase().includes(searchLower)
            );
        }

        // Return filtered results with 200 OK status
        res.status(200).json({
            success: true,
            count: result.length,
            data: result
        });
    } catch (error) {
        // Let the global error handler deal with this
        next(error);
    }
});

/**
 * GET /books/:id
 * 
 * Retrieves a single book by its ID.
 * 
 * @param {number} req.params.id - The numeric ID of the book
 * @returns {Object} Book object if found, 404 error if not found
 */
router.get('/:id', (req, res, next) => {
    try {
        // Validate that ID is a positive integer
        validateId(req.params.id);

        const id = parseInt(req.params.id, 10);

        // Find the book by ID
        const book = getBookById(id);

        // If not found, throw NotFoundError (will be caught by error handler)
        if (!book) {
            throw new NotFoundError('Book', id);
        }

        // Return the book with 200 OK status
        res.status(200).json({
            success: true,
            data: book
        });
    } catch (error) {
        next(error);
    }
});

/**
 * POST /books
 * 
 * Creates a new book.
 * 
 * Request body should contain:
 * - title (required): String
 * - author (required): String  
 * - genre (required): String from predefined list
 * - publishedYear (required): Integer between 1000 and current year
 * - rating (optional): Number between 0 and 5
 * 
 * @example
 * POST /books
 * {
 *   "title": "The Hobbit",
 *   "author": "J.R.R. Tolkien",
 *   "genre": "Fantasy",
 *   "publishedYear": 1937,
 *   "rating": 4.7
 * }
 */
router.post('/', (req, res, next) => {
    try {
        // Validate the incoming request data
        validateCreateBook(req.body);

        // Create the new book in storage
        const newBook = createBook(req.body);

        // Return 201 Created status with the new book
        // 201 is the standard HTTP status for successful resource creation
        res.status(201).json({
            success: true,
            data: newBook
        });
    } catch (error) {
        next(error);
    }
});

/**
 * PUT /books/:id
 * 
 * Updates an existing book by ID.
 * 
 * This is a full replacement update - all fields must be provided.
 * For partial updates, use PATCH instead (not implemented in this example).
 * 
 * @example
 * PUT /books/1
 * {
 *   "title": "The Hobbit",
 *   "author": "J.R.R. Tolkien",
 *   "genre": "Fantasy",
 *   "publishedYear": 1937,
 *   "rating": 4.8
 * }
 */
router.put('/:id', (req, res, next) => {
    try {
        // Validate ID format
        validateId(req.params.id);

        const id = parseInt(req.params.id, 10);

        // First check if the book exists
        const existingBook = getBookById(id);
        if (!existingBook) {
            throw new NotFoundError('Book', id);
        }

        // Validate the update data
        validateUpdateBook(req.body);

        // Update the book in storage
        const updatedBook = updateBook(id, req.body);

        // Return 200 OK with updated book
        res.status(200).json({
            success: true,
            data: updatedBook
        });
    } catch (error) {
        next(error);
    }
});

/**
 * DELETE /books/:id
 * 
 * Deletes a book by ID.
 * 
 * @returns {Object} Success message if deleted, 404 error if not found
 */
router.delete('/:id', (req, res, next) => {
    try {
        // Validate ID format
        validateId(req.params.id);

        const id = parseInt(req.params.id, 10);

        // Check if book exists before attempting deletion
        const existingBook = getBookById(id);
        if (!existingBook) {
            throw new NotFoundError('Book', id);
        }

        // Delete the book from storage
        const deleted = deleteBook(id);

        // Return 200 OK with success message
        // We use 200 instead of 204 because we want to return a response body
        res.status(200).json({
            success: true,
            message: `Book with id ${id} has been deleted`
        });
    } catch (error) {
        next(error);
    }
});

// Export the router so it can be mounted in server.js
module.exports = router;
```

