/**
 * @fileoverview Global error handling middleware.
 * 
 * This module provides a centralized error handler that catches all errors
 * and returns appropriate HTTP responses. We use this pattern because:
 * 1. It prevents duplicate error handling code in every route
 * 2. It ensures consistent error response format across the API
 * 3. It separates error handling logic from business logic
 * 4. It can log errors for debugging while returning safe messages to clients
 * 
 * Express error-handling middleware has a special signature: (err, req, res, next)
 */

/**
 * Global error handler middleware.
 * 
 * @param {Error} err - The error object
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function
 */
function errorHandler(err, req, res, next) {
    // Log the full error for debugging (don't expose to client)
    console.error('Error occurred:', {
        message: err.message,
        stack: err.stack,
        statusCode: err.statusCode,
        name: err.name
    });

    // Determine status code and response based on error type
    if (err.name === 'ValidationError') {
        // Validation errors get 400 Bad Request with detailed validation info
        res.status(400).json({
            success: false,
            error: err.message,
            details: err.details || []
        });
    } else if (err.name === 'NotFoundError') {
        // Not found errors get 404 with resource-specific message
        res.status(404).json({
            success: false,
            error: err.message
        });
    } else if (err.statusCode >= 500) {
        // Server errors get 500 with generic message (don't expose internal details)
        res.status(500).json({
            success: false,
            error: 'Internal server error'
        });
    } else {
        // For any other errors, return the error message and status code
        res.status(err.statusCode || 500).json({
            success: false,
            error: err.message
        });
    }
}

// Export the error handler
module.exports = errorHandler;
```

