/**
 * @fileoverview Main server file for the Book REST API.
 * 
 * This is the entry point of our application. It sets up Express,
 * configures middleware, mounts routes, and starts the HTTP server.
 * 
 * Architecture decisions:
 * 1. We use modular route files (routes/books.js, routes/stats.js) for separation of concerns
 * 2. Error handling is centralized in middleware/errorHandler.js
 * 3. Data access is separated into data.js for testability
 * 4. Validation is in its own module for reusability
 */

const express = require('express');
const path = require('path');

// Import route modules
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// Import error handler middleware
const errorHandler = require('./middleware/errorHandler');

// Create Express application instance
const app = express();

// Configure port (use environment variable or default to 3000)
const PORT = process.env.PORT || 3000;

/**
 * Middleware configuration:
 * 
 * 1. express.json() - Parses incoming JSON requests into req.body
 *    This is essential for POST/PUT requests that send JSON data
 * 
 * 2. express.urlencoded() - Parses URL-encoded form data
 *    We set extended: true to support nested objects (though we don't use them here)
 */
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

/**
 * Request logging middleware.
 * 
 * This logs each request with timestamp, method, URL, and response status.
 * It's useful for debugging and monitoring API usage.
 */
app.use((req, res, next) => {
    const timestamp = new Date().toISOString();
    console.log(`[${timestamp}] ${req.method} ${req.url}`);

    // Continue to the next middleware/route handler
    next();
});

/**
 * Mount route modules on their respective paths.
 * 
 * We mount bookRoutes on '/books' and statsRoutes on '/stats'.
 * This means all routes defined in those files will be prefixed accordingly.
 */
app.use('/books', bookRoutes);
app.use('/stats', statsRoutes);

/**
 * Root endpoint for API health check.
 * 
 * GET / - Returns basic API information
 */
app.get('/', (req, res) => {
    res.json({
        success: true,
        message: 'Book REST API is running',
        endpoints: {
            books: '/books',
            stats: '/stats'
        },
        documentation: 'See README.md for usage examples'
    });
});

/**
 * 404 handler for undefined routes.
 * 
 * This catches requests to paths that don't match any defined route.
 * It must be placed AFTER all route definitions but BEFORE the error handler.
 */
app.use((req, res) => {
    res.status(404).json({
        success: false,
        error: `Route ${req.method} ${req.url} not found`
    });
});

/**
 * Global error handling middleware.
 * 
 * This must be the LAST middleware in the chain.
 * It catches all errors thrown by route handlers and returns appropriate responses.
 */
app.use(errorHandler);

/**
 * Start the HTTP server.
 * 
 * We use arrow function syntax for cleaner code.
 * The callback logs a success message when the server starts listening.
 */
app.listen(PORT, () => {
    console.log(`Book REST API server running on port ${PORT}`);
    console.log(`API base URL: http://localhost:${PORT}`);
    console.log('\nAvailable endpoints:');
    console.log('  GET    /              - API information');
    console.log('  GET    /books         - List all books (with optional filtering)');
    console.log('  GET    /books/:id     - Get single book by ID');
    console.log('  POST   /books         - Create new book');
    console.log('  PUT    /books/:id     - Update existing book');
    console.log('  DELETE /books/:id     - Delete book');
    console.log('  GET    /stats         - Get statistics');
});

// Export the app for testing purposes
module.exports = app;
