## Arquivo 2: `src/models/book.js`

```javascript
/**
 * @fileoverview Modelo de dados para livros usando armazenamento em memória.
 *
 * Escolha do padrão: Usamos um array simples em vez de um banco de dados real
 * porque este é um exemplo educacional. Arrays oferecem:
 *   - Zero configuração de infraestrutura (sem instalação de DB)
 *   - Operações O(1) para acesso por índice, O(n) para busca linear
 *   - Facilita o entendimento dos conceitos de CRUD sem distrações
 *
 * Em produção, substituiríamos este módulo por um serviço que usa MongoDB,
 * PostgreSQL ou outro banco, mantendo a mesma interface (API do modelo).
 */

// ---------------------------------------------------------------------------
// Armazenamento em memória
// ---------------------------------------------------------------------------
/**
 * Array que armazena todos os livros.
 *
 * Por que array e não objeto? Arrays preservam ordem de inserção e são mais
 * intuitivos para operações de listagem/filtragem sequencial. Objetos (maps)
 * seriam melhores se buscássemos predominantemente por ID, mas arrays são
 * mais familiares e permitem iteração ordenada — importante para paginação
 * futura e ordenação por campos como título ou ano.
 */
const books = [];

/**
 * Contador global para geração automática de IDs únicos.
 *
 * Usamos um contador simples em vez de UUIDs porque:
 *   - IDs numéricos são mais legíveis em exemplos educacionais
 *   - Evitam colisões sem necessidade de bibliotecas externas
 *   - São eficientes para comparações e indexação
 *
 * Em produção, consideraríamos UUID v4 ou snowflake IDs para garantir
 * unicidade distribuída.
 */
let nextId = 1;

// ---------------------------------------------------------------------------
// Classe de validação de entrada
// ---------------------------------------------------------------------------

/**
 * Erro personalizado lançado quando os dados de entrada são inválidos.
 *
 * Herdamos de Error para que o erro seja reconhecido nativamente pelo Node.js,
 * mas adicionamos um campo `statusCode` (400) para que o middleware de erros
 * possa diferenciar erros de validação de outros tipos de erro.
 */
class ValidationError extends Error {
  /**
   * @param {string} message - Descrição do erro de validação
   */
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

// ---------------------------------------------------------------------------
// Funções do modelo (CRUD)
// ---------------------------------------------------------------------------

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista de objetos livro
 */
function getAllBooks() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - ID do livro a ser buscado
 * @returns {Object|null} Livro encontrado ou null se não existir
 *
 * Usamos find() em vez de acesso por índice porque os IDs são gerados
 * automaticamente e podem ter lacunas (se livros forem deletados).
 */
function getBookById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * Cria um novo livro com validação de campos obrigatórios.
 *
 * @param {Object} data - Dados do livro a ser criado
 * @param {string} data.title - Título do livro (obrigatório, não vazio)
 * @param {string} data.author - Autor do livro (obrigatório, não vazio)
 * @param {number} [data.year] - Ano de publicação (opcional, deve ser numérico)
 * @param {string} [data.genre] - Gênero literário (opcional)
 * @returns {Object} Livro criado com ID atribuído automaticamente
 * @throws {ValidationError} Se campos obrigatórios estiverem ausentes ou inválidos
 *
 * Padrão async/await: Embora esta operação seja síncrona, mantemos a assinatura
 * consistente com operações de banco de dados futuras. Isso facilita a migração
 * para um storage assíncrono sem alterar as rotas que chamam este modelo.
 */
async function createBook(data) {
  // Validação dos campos obrigatórios
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    throw new ValidationError('O campo "title" é obrigatório e deve ser uma string não vazia.');
  }
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    throw new ValidationError('O campo "author" é obrigatório e deve ser uma string não vazia.');
  }

  // Validação opcional do ano
  if (data.year !== undefined && (typeof data.year !== 'number' || !Number.isInteger(data.year))) {
    throw new ValidationError('O campo "year" deve ser um número inteiro.');
  }

  const book = {
    id: nextId++,
    title: data.title.trim(),
    author: data.author.trim(),
    year: data.year ?? null,       // null é mais semântico que undefined para JSON
    genre: data.genre ?? null,
    createdAt: new Date().toISOString()
  };

  books.push(book);
  return book;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} data - Campos a serem atualizados (parcial)
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 * @throws {ValidationError} Se campos obrigatórios forem fornecidos com valores inválidos
 *
 * Padrão de atualização parcial (PATCH semântico via PUT): Permitimos que o
 * cliente envie apenas os campos que deseja alterar. Campos não enviados são
 * mantidos inalterados. Isso segue a convenção REST de que PUT pode ser usado
 * para atualizações parciais em APIs simples, embora tecnicamente PATCH seja
 * mais apropriado para isso. Para este exemplo educacional, simplificamos
 * usando PUT para ambos os casos.
 */
async function updateBook(id, data) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return null;

  // Validação condicional: só valida campos que o cliente enviou
  if (data.title !== undefined) {
    if (typeof data.title !== 'string' || data.title.trim() === '') {
      throw new ValidationError('O campo "title" deve ser uma string não vazia.');
    }
    books[index].title = data.title.trim();
  }

  if (data.author !== undefined) {
    if (typeof data.author !== 'string' || data.author.trim() === '') {
      throw new ValidationError('O campo "author" deve ser uma string não vazia.');
    }
    books[index].author = data.author.trim();
  }

  if (data.year !== undefined) {
    if (typeof data.year !== 'number' || !Number.isInteger(data.year)) {
      throw new ValidationError('O campo "year" deve ser um número inteiro.');
    }
    books[index].year = data.year;
  }

  if (data.genre !== undefined) {
    books[index].genre = data.genre;
  }

  return books[index];
}

/**
 * Exclui um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser excluído
 * @returns {boolean} True se o livro foi encontrado e excluído, false caso contrário
 *
 * Usamos splice() em vez de filter() porque:
 *   - splice() modifica o array original in-place (mais eficiente para arrays pequenos)
 *   - Retorna o elemento removido, permitindo verificação imediata
 *   - Em arrays grandes, filter() criaria uma cópia completa; splice() é O(n) no pior caso
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros armazenados.
 *
 * @returns {Object} Estatísticas contendo:
 *   - total: número total de livros
 *   - averageYear: ano médio de publicação (null se vazio)
 *   - booksByGenre: contagem de livros por gênero
 *   - booksByAuthor: contagem de livros por autor
 *
 * Esta função demonstra como extrair valor analítico dos dados em memória.
 * Em produção, essas estatísticas seriam calculadas via queries agregadas no banco.
 */
function getStats() {
  const total = books.length;

  // Ano médio: soma todos os anos válidos e divide pela quantidade
  const yearsWithData = books.filter(b => b.year !== null);
  const averageYear = yearsWithData.length > 0
    ? yearsWithData.reduce((sum, b) => sum + b.year, 0) / yearsWithData.length
    : null;

  // Agrupamento por gênero e autor usando reduce para eficiência O(n)
  const booksByGenre = {};
  const booksByAuthor = {};

  for (const book of books) {
    // Gênero: usa "Unknown" como fallback para livros sem gênero definido
    const genre = book.genre || 'Unknown';
    booksByGenre[genre] = (booksByGenre[genre] || 0) + 1;

    booksByAuthor[book.author] = (booksByAuthor[book.author] || 0) + 1;
  }

  return { total, averageYear: averageYear ? Math.round(averageYear * 100) / 100 : null, booksByGenre, booksByAuthor };
}

// ---------------------------------------------------------------------------
// Exportações (padrão CommonJS)
// ---------------------------------------------------------------------------
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  ValidationError
};
```

**Explicação geral do modelo:** O modelo separa completamente a lógica de dados da camada de rotas. Isso segue o princípio de responsabilidade única: as rotas se preocupam com HTTP (códigos de status, headers), enquanto o modelo se preocupa com dados (validação, persistência). A classe `ValidationError` herda de `Error` para integração nativa com o sistema de exceções do Node.js, mas adiciona `statusCode` para que o middleware de erros possa responder com 400 em vez de 500. O uso de `async/await` mesmo em operações síncronas é uma escolha deliberada de futuro-proofing: se no futuro migrarmos para um banco de dados, as rotas não precisarão ser alteradas.

