## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * @fileoverview Rotas REST para recursos de livros.
 *
 * Convenções REST adotadas:
 *   - GET    /books       → lista todos (com filtragem opcional)
 *   - GET    /books/:id   → obtém um específico
 *   - POST   /books       → cria um novo
 *   - PUT    /books/:id   → atualiza completamente (ou parcialmente neste exemplo)
 *   - DELETE /books/:id   → exclui
 *
 * Por que PUT e não PATCH? Para este exemplo educacional, usamos PUT para
 * atualizações parciais por simplicidade. Em uma API production-grade,
 * separaríamos em PUT (substituição total) e PATCH (atualização parcial).
 *
 * Padrão async/await: Cada handler é async porque o modelo usa async/await.
 * Mesmo que a operação seja síncrona internamente, manter a assinatura async
 * evita problemas se o modelo for substituído por uma implementação assíncrona.
 */

const express = require('express');
const router = express.Router();
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  ValidationError
} = require('../models/book');

// ---------------------------------------------------------------------------
// GET /books — Listar todos os livros com filtragem opcional
// ---------------------------------------------------------------------------

/**
 * @route   GET /books
 * @desc    Retorna lista de todos os livros
 * @access  Public
 *
 * Query params opcionais:
 *   - author: filtra por autor (case-insensitive)
 *   - genre:  filtra por gênero (case-insensitive)
 *   - search: busca por título ou autor (substring match)
 *
 * @example curl "http://localhost:3000/books?author=tolkien"
 * @example curl "http://localhost:3000/books?genre=ficcao&search=senhor"
 */
router.get('/', async (req, res, next) => {
  try {
    let result = getAllBooks();

    // Filtragem por autor (case-insensitive para melhor UX)
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter(book => book.author.toLowerCase().includes(authorFilter));
    }

    // Filtragem por gênero
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter(book => (book.genre || 'unknown').toLowerCase() === genreFilter);
    }

    // Busca por substring em título ou autor
    if (req.query.search) {
      const searchLower = req.query.search.toLowerCase();
      result = result.filter(book =>
        book.title.toLowerCase().includes(searchLower) ||
        book.author.toLowerCase().includes(searchLower)
      );
    }

    res.json({ success: true, count: result.length, data: result });
  } catch (err) {
    next(err); // Passa para o middleware de erro
  }
});

// ---------------------------------------------------------------------------
// GET /books/:id — Obter livro por ID
// ---------------------------------------------------------------------------

/**
 * @route   GET /books/:id
 * @desc    Retorna um livro específico pelo ID
 * @access  Public
 *
 * @param {number} id - ID numérico do livro na URL
 *
 * @example curl "http://localhost:3000/books/1"
 */
router.get('/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    // Validação do parâmetro de URL: deve ser um número inteiro válido
    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro válido.');
    }

    const book = getBookById(id);
    if (!book) {
      // Criamos um erro personalizado com statusCode 404
      const err = new Error(`Livro com ID ${id} não encontrado.`);
      err.statusCode = 404;
      throw err;
    }

    res.json({ success: true, data: book });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// POST /books — Criar novo livro
// ---------------------------------------------------------------------------

/**
 * @route   POST /books
 * @desc    Cria um novo livro
 * @access  Public
 *
 * Body JSON esperado:
 *   {
 *     "title": "O Senhor dos Anéis",
 *     "author": "J.R.R. Tolkien",
 *     "year": 1954,
 *     "genre": "fantasia"
 *   }
 *
 * @example curl -X POST http://localhost:3000/books \
 *           -H "Content-Type: application/json" \
 *           -d '{"title":"1984","author":"George Orwell","year":1949}'
 */
router.post('/', async (req, res, next) => {
  try {
    // Validação básica do body: deve ser um objeto com pelo menos title e author
    if (!req.body || typeof req.body !== 'object') {
      throw new ValidationError('O corpo da requisição deve ser um JSON válido.');
    }

    const book = await createBook(req.body);
    // 201 Created é o código HTTP semântico para recursos criados com sucesso
    res.status(201).json({ success: true, data: book });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// PUT /books/:id — Atualizar livro existente
// ---------------------------------------------------------------------------

/**
 * @route   PUT /books/:id
 * @desc    Atualiza um livro existente
 * @access  Public
 *
 * Body JSON: campos opcionais a serem atualizados
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *           -H "Content-Type: application/json" \
 *           -d '{"year":1955}'
 */
router.put('/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro válido.');
    }

    const updatedBook = await updateBook(id, req.body);
    if (!updatedBook) {
      const err = new Error(`Livro com ID ${id} não encontrado.`);
      err.statusCode = 404;
      throw err;
    }

    res.json({ success: true, data: updatedBook });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// DELETE /books/:id — Excluir livro
// ---------------------------------------------------------------------------

/**
 * @route   DELETE /books/:id
 * @desc    Exclui um livro pelo ID
 * @access  Public
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro válido.');
    }

    const deleted = deleteBook(id);
    if (!deleted) {
      const err = new Error(`Livro com ID ${id} não encontrado.`);
      err.statusCode = 404;
      throw err;
    }

    // 204 No Content é o código semântico para exclusão bem-sucedida sem body
    res.status(204).send();
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

**Explicação das rotas:** Cada handler segue o padrão `try/catch` + `next(err)` para que erros sejam capturados e passados ao middleware centralizado. A validação de `parseInt(req.params.id, 10)` é essencial porque parâmetros de URL chegam como strings — sem essa conversão, `getBookById('1')` não encontraria o livro (pois `id === '1'` seria false quando o ID armazenado é numérico). O uso de códigos HTTP semânticos (201 para criação, 204 para exclusão) segue as especificações RFC 7231. A filtragem com `toLowerCase()` nas queries garante que buscas sejam case-insensitive, melhorando a experiência do usuário.

