```javascript
/**
 * @fileoverview Rotas para estatísticas agregadas dos livros.
 *
 * Esta rota demonstra como expor dados analíticos derivados sem violar
 * o princípio de que cada recurso deve ter sua própria URL. "/stats" é um
 * sub-recurso do conjunto de livros, não um livro em si.
 */

const express = require('express');
const router = express.Router();
const { getStats } = require('../models/book');

/**
 * @route   GET /stats
 * @desc    Retorna estatísticas agregadas sobre os livros
 * @access  Public
 *
 * Resposta de exemplo:
 * {
 *   "success": true,
 *   "data": {
 *     "total": 5,
 *     "averageYear": 1972,
 *     "booksByGenre": { "fantasia": 2, "ficcao": 3 },
 *     "booksByAuthor": { "J.R.R. Tolkien": 2, "George Orwell": 3 }
 *   }
 * }
 *
 * @example curl "http://localhost:3000/stats"
 */
router.get('/', async (req, res, next) => {
  try {
    const stats = getStats();
    res.json({ success: true, data: stats });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

**Explicação:** A rota de estatísticas é intencionalmente simples para demonstrar que endpoints podem retornar dados derivados/agregados sem ser um recurso CRUD tradicional. Em uma API mais complexa, poderíamos adicionar paginação, ordenação ou filtros temporais às estatísticas.

